mapper.select:
SELECT id, task_id, trial_no, trace_id, query_text, standard_answer, actual_answer, recall_score, precision_score, f1_score, top3_hit_rate, mrr_score, ndcg_score, map_score, answer_similarity, context_precision, context_recall, context_relevance, faithfulness_score, relevance_score, hallucination_flag, completeness_score, answer_correctness, overall_score, eval_detail, create_time, tool_selection_score, tool_param_score, tool_call_score, intent_score, branch_score, reasoning_score, agent_decision_score FROM eval_result WHERE task_id = #{taskId}
AND trial_no = #{trial}
ORDER BY create_time DESC LIMIT #{size} OFFSET #{offset}
